import React from 'react';
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ComposedChart, Area } from 'recharts';

const ComplaintTrackingChart = ({ analyzedData }) => {
  // Cyberpunk color palette with green and black focus
  const colors = {
    neon: {
      green: '#00ff41',      // Matrix green
      brightGreen: '#39ff14', // Bright lime green
      darkGreen: '#008f11',  // Dark matrix green
      accent: '#0abdc6',     // Subtle cyan accent
      yellow: '#caff70'      // Subtle yellow highlight
    },
    dark: {
      base: '#0d0208',       // Almost black
      secondary: '#0f100f',  // Very dark gray
      accent: '#121212'      // Dark charcoal
    },
    text: {
      primary: '#00ff41',    // Matrix green
      secondary: '#465b49'   // Muted green
    }
  };

  // Exit early if no data
  if (!analyzedData || !analyzedData.chunks || analyzedData.chunks.length === 0) {
    return (
      <div className="flex flex-col items-center w-full max-w-4xl mx-auto p-4 rounded-lg shadow-2xl border border-green-500" style={{
        background: `linear-gradient(135deg, ${colors.dark.base} 0%, ${colors.dark.secondary} 100%)`,
        boxShadow: `0 0 20px ${colors.neon.darkGreen}`
      }}>
        <h2 className="text-2xl font-bold mb-4 font-mono uppercase tracking-widest" style={{color: colors.neon.green}}>TERMINAL // NO DATA AVAILABLE</h2>
      </div>
    );
  }

  // Process the chunks data for the chart
  const data = analyzedData.chunks.map((chunk, index) => {
    // Extract start and end time
    let timeRange = `Chunk ${index + 1}`;
    if (chunk.timestamp) {
      const timestamp = new Date(chunk.timestamp);
      timeRange = timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }

    // Calculate complaint level (0, 1, or 2 based on confidence)
    let complaintLevel = 0;
    if (chunk.isComplaint) {
      complaintLevel = chunk.confidence > 0.75 ? 2 : 1;
    }

    // Extract the first few words from the first utterance for description
    // More robust version with additional checks
    let description = '';
    try {
      // Check if chunk has text first as a fallback
      if (chunk.text) {
        // Use chunk text directly if available
        description = chunk.text.split(' ').slice(0, 5).join(' ');
        if (chunk.text.split(' ').length > 5) {
          description += '...';
        }
      } 
      // Otherwise try to get it from utterances
      else if (chunk.utterances && Array.isArray(chunk.utterances) && chunk.utterances.length > 0) {
        const utterance = chunk.utterances[0];

        // Check if the utterance has a text property
        if (utterance && typeof utterance.text === 'string') {
          description = utterance.text.split(' ').slice(0, 5).join(' ');
          if (utterance.text.split(' ').length > 5) {
            description += '...';
          }
        }
        // Check if the utterance itself is a string
        else if (utterance && typeof utterance === 'string') {
          description = utterance.split(' ').slice(0, 5).join(' ');
          if (utterance.split(' ').length > 5) {
            description += '...';
          }
        }
      }

      // If still empty, provide a default
      if (!description) {
        description = `Data Point ${index + 1}`;
      }
    } catch (error) {
      // Fallback for any unexpected errors
      console.error('Error processing description:', error);
      description = `Chunk ${index + 1}`;
    }

    return {
      window: `Window ${index + 1}`,
      timeRange,
      complaintLevel,
      complaintPercentage: Math.round(chunk.confidence * 100),
      description
    };
  });

  // Calculate the average complaint percentage
  const totalPercentage = data.reduce((sum, item) => sum + item.complaintPercentage, 0);
  const averagePercentage = (totalPercentage / data.length).toFixed(1);

  // Find the peak window (highest complaint percentage)
  const peakWindow = [...data].sort((a, b) => b.complaintPercentage - a.complaintPercentage)[0]?.window || 'NONE';

  // Calculate runtime from first to last chunk timestamp if available
  let runtime = 'N/A';
  if (analyzedData.chunks.length > 1 && analyzedData.chunks[0].timestamp && analyzedData.chunks[analyzedData.chunks.length - 1].timestamp) {
    const firstTime = new Date(analyzedData.chunks[0].timestamp).getTime();
    const lastTime = new Date(analyzedData.chunks[analyzedData.chunks.length - 1].timestamp).getTime();
    const diffSeconds = Math.floor((lastTime - firstTime) / 1000);
    const minutes = Math.floor(diffSeconds / 60);
    const seconds = diffSeconds % 60;
    runtime = `${minutes}M:${seconds}S`;
  }

  // Calculate summary stats
  const totalUtterances = analyzedData.utterances ? analyzedData.utterances.length : 0;
  const complaintChunks = analyzedData.chunks.filter(chunk => chunk.isComplaint).length;
  const complaintPercentage = Math.round((complaintChunks / analyzedData.chunks.length) * 100);

  // Count speakers if possible
  let callerCount = 0;
  let agentCount = 0;

  if (analyzedData.utterances) {
    analyzedData.utterances.forEach(utterance => {
      if (utterance.speaker && utterance.speaker.toLowerCase().includes('caller')) {
        callerCount++;
      } else if (utterance.speaker && utterance.speaker.toLowerCase().includes('agent')) {
        agentCount++;
      }
    });
  }

  // Get analysis period if available
  let analysisPeriod = '';
  if (analyzedData.chunks && analyzedData.chunks.length > 0) {
    const timestamps = analyzedData.chunks
      .filter(chunk => chunk.timestamp)
      .map(chunk => new Date(chunk.timestamp).getTime());

    if (timestamps.length > 0) {
      const firstTimestamp = new Date(Math.min(...timestamps));
      const lastTimestamp = new Date(Math.max(...timestamps));
      const duration = ((lastTimestamp - firstTimestamp) / 1000).toFixed(1);

      analysisPeriod = `${firstTimestamp.toLocaleTimeString()} - ${lastTimestamp.toLocaleTimeString()} (${duration} seconds)`;
    }
  }

  // Determine complaint severity
  let severity = 'Low';
  if (complaintPercentage > 75) {
    severity = 'High';
  } else if (complaintPercentage > 30) {
    severity = 'Medium';
  }

  return (
    <div className="flex flex-col w-full mx-auto" style={{
      background: colors.dark.base,
      maxHeight: '100vh',
      overflow: 'hidden'
    }}>
      {/* Main terminal container */}
      <div className="flex flex-col w-full p-3 rounded-lg shadow-2xl border border-green-500" style={{
        background: `linear-gradient(135deg, ${colors.dark.base} 0%, ${colors.dark.secondary} 100%)`,
        boxShadow: `0 0 20px ${colors.neon.darkGreen}`
      }}>
        <div className="flex justify-center items-center mb-2">
          <h2 className="text-2xl font-bold font-mono uppercase tracking-widest" style={{color: colors.neon.green}}>
            TERMINAL // CUSTOMER COMPLAINT MATRIX
          </h2>
        </div>

        {/* Top stats row - 4 cyberpunk-styled stat boxes */}
        <div className="grid grid-cols-4 gap-2 mb-2">
          {/* Complaint Severity */}
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" 
               style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">Complaint Severity</span>
            <span className="text-xl font-bold font-mono" style={{
              color: severity === 'High' ? '#ff5555' : 
                     severity === 'Medium' ? colors.neon.yellow : 
                     colors.neon.green
            }}>
              {severity}
            </span>
            <span className="text-xxs font-mono text-gray-400">Based on percentage</span>
          </div>

          {/* Complaint Chunks */}
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" 
               style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">Complaint Chunks</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>
              {complaintChunks}/{analyzedData.chunks.length}
            </span>
            <span className="text-xxs font-mono text-gray-400">{complaintPercentage}% of chunks</span>
          </div>

          {/* Total Utterances */}
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" 
               style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">Total Utterances</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>
              {totalUtterances}
            </span>
            <span className="text-xxs font-mono text-gray-400">
              {callerCount > 0 || agentCount > 0 ? `${callerCount} caller, ${agentCount} agent` : ''}
            </span>
          </div>

          {/* Caller Complaints */}
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" 
               style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">Caller Complaints</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>
              ~{complaintChunks}/{callerCount || 4}
            </span>
            <span className="text-xxs font-mono text-gray-400">Estimated from chunks</span>
          </div>
        </div>

        {/* Main chart area */}
        <div className="w-full mb-2 border border-green-400 rounded-lg p-2" style={{
          background: 'rgba(0, 20, 0, 0.7)', 
          boxShadow: `0 0 15px ${colors.neon.darkGreen}`,
          height: '280px'
        }}>
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={data} margin={{ top: 10, right: 30, left: 20, bottom: 40 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,255,65,0.1)" />
              <XAxis 
                dataKey="window" 
                angle={-45} 
                textAnchor="end" 
                height={60} 
                tick={{ fontSize: 10, fill: colors.text.primary, fontFamily: 'monospace' }}
                stroke={colors.text.secondary}
              />
              <YAxis 
                yAxisId="left" 
                label={{ value: 'LEVEL', angle: -90, position: 'insideLeft', fill: colors.neon.green, fontSize: 10, fontFamily: 'monospace' }} 
                tick={{ fill: colors.text.primary, fontFamily: 'monospace', fontSize: 10 }}
                stroke={colors.text.secondary}
              />
              <YAxis 
                yAxisId="right" 
                orientation="right" 
                label={{ value: '%', angle: 90, position: 'insideRight', fill: colors.neon.green, fontSize: 10, fontFamily: 'monospace' }} 
                tick={{ fill: colors.text.primary, fontFamily: 'monospace', fontSize: 10 }}
                stroke={colors.text.secondary}
              />
              <Tooltip
                contentStyle={{ 
                  backgroundColor: 'rgba(0, 20, 0, 0.9)', 
                  borderColor: colors.neon.green,
                  color: colors.neon.green,
                  boxShadow: `0 0 10px ${colors.neon.green}`,
                  borderRadius: '0px',
                  fontFamily: 'monospace'
                }}
                formatter={(value, name) => {
                  if (name === "complaintLevel") {
                    const levels = ["None", "Mild", "Strong"];
                    return [levels[value], "LEVEL"];
                  }
                  return [value + "%", "RATIO"];
                }}
                labelFormatter={(value, items) => {
                  const item = data.find(d => d.window === value);
                  return `${value} (${item.timeRange})`;
                }}
              />
              <Legend 
                wrapperStyle={{
                  color: colors.neon.green,
                  fontFamily: 'monospace',
                  fontSize: 10
                }}
              />
              <Bar 
                yAxisId="left"
                dataKey="complaintLevel" 
                fill={colors.neon.darkGreen}
                name="Complaint Level"
                barSize={30}
                animationDuration={1500}
                style={{filter: `drop-shadow(0 0 8px ${colors.neon.darkGreen})`}}
              />
              <Line 
                yAxisId="right"
                type="monotone" 
                dataKey="complaintPercentage" 
                stroke={colors.neon.green}
                name="Complaint %"
                strokeWidth={3}
                dot={{ fill: colors.neon.green, r: 4, strokeWidth: 0 }}
                activeDot={{ fill: colors.neon.brightGreen, r: 6, strokeWidth: 0 }}
                animationDuration={1500}
                style={{filter: `drop-shadow(0 0 8px ${colors.neon.green})`}}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>

        {/* Bottom stats and table combined section */}
        <div className="grid grid-cols-4 gap-2">
          {/* System diagnostics in a row on the left */}
          <div className="col-span-1">
            <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col h-full" 
                 style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
              <h3 className="text-sm font-mono font-semibold mb-1 text-center uppercase tracking-wider" style={{color: colors.neon.green}}>
                // SYSTEM DIAGNOSTICS //
              </h3>
              <div className="flex-1 flex flex-col justify-between">
                <div className="flex flex-col mb-1">
                  <span className="text-xs font-mono text-gray-400 uppercase">CMPLNT.RATIO</span>
                  <span className="text-sm font-bold font-mono" style={{color: colors.neon.green}}>{averagePercentage}%</span>
                </div>
                <div className="flex flex-col mb-1">
                  <span className="text-xs font-mono text-gray-400 uppercase">PEAK.ALARM</span>
                  <span className="text-sm font-bold font-mono" style={{color: colors.neon.green}}>{peakWindow}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-xs font-mono text-gray-400 uppercase">RUNTIME</span>
                  <span className="text-sm font-bold font-mono" style={{color: colors.neon.green}}>{runtime}</span>
                </div>
                <div className="flex flex-col mt-1">
                  <span className="text-xs font-mono text-gray-400 uppercase">SESSION</span>
                  <span className="text-sm font-bold font-mono" style={{color: colors.neon.green}}>
                    XR-{Math.floor(Math.random() * 10000)}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Conversation datastream table on the right (3 cols) */}
          <div className="col-span-3">
            <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 h-full flex flex-col" 
                 style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
              <h3 className="text-sm font-mono font-semibold mb-1 text-center uppercase tracking-wider" style={{color: colors.neon.green}}>
                // CONVERSATION DATASTREAM //
              </h3>
              <div className="overflow-hidden flex-1" style={{maxHeight: '200px'}}>
                <table className="w-full bg-black border border-green-500 text-sm">
                  <thead>
                    <tr className="bg-gray-900 border-b border-green-500">
                      <th className="p-1 border-r border-green-500 font-mono text-xxs" style={{color: colors.neon.green}}>SEQUENCE</th>
                      <th className="p-1 border-r border-green-500 font-mono text-xxs" style={{color: colors.neon.green}}>TIMESTAMP</th>
                      <th className="p-1 border-r border-green-500 font-mono text-xxs" style={{color: colors.neon.green}}>STATUS</th>
                      <th className="p-1 font-mono text-xxs" style={{color: colors.neon.green}}>DATA_INPUT</th>
                    </tr>
                  </thead>
                  <tbody style={{fontFamily: 'monospace'}}>
                    {data.map((item, index) => (
                      <tr key={index} className={`border-b border-green-900 ${index % 2 === 0 ? 'bg-black' : 'bg-gray-900'}`}>
                        <td className="p-1 border-r border-green-900 font-mono font-medium text-xxs" style={{color: colors.neon.green}}>{item.window}</td>
                        <td className="p-1 border-r border-green-900 font-mono text-xxs" style={{color: colors.neon.darkGreen}}>{item.timeRange}</td>
                        <td className="p-1 border-r border-green-900">
                          <span className={`px-1 py-0 text-xxs font-semibold font-mono
                            ${item.complaintLevel === 0 ? 'bg-black text-green-400 border border-green-500' : 
                              item.complaintLevel === 1 ? 'bg-black text-yellow-400 border border-yellow-500' : 
                              'bg-black text-red-400 border border-red-500'}`}
                            style={{
                              boxShadow: item.complaintLevel === 0 ? `0 0 3px ${colors.neon.green}` : 
                                        item.complaintLevel === 1 ? `0 0 3px ${colors.neon.yellow}` : 
                                        `0 0 3px red`
                            }}>
                            {item.complaintLevel === 0 ? 'STABLE' : 
                             item.complaintLevel === 1 ? 'CAUTION' : 'ALERT'}
                          </span>
                        </td>
                        <td className="p-1 font-mono text-xxs" style={{color: colors.neon.darkGreen}}>{item.description}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>

        {/* Footer with analysis period */}
        <div className="w-full text-center mt-2 font-mono text-xxs" style={{color: colors.neon.darkGreen}}>
          <p>CORP//MAINFRAME ACCESS [v3.5.2] © 2025 [RESTRICTED] | Analysis period: {analysisPeriod || 'N/A'}</p>
        </div>
      </div>
    </div>
  );
};

// Add missing text-xxs class
const styleTag = document.createElement('style');
styleTag.innerHTML = `
  .text-xxs {
    font-size: 0.65rem;
    line-height: 0.85rem;
  }
  .text-xl {
    font-size: 1.25rem;
    line-height: 1.75rem;
  }
  .text-sm {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }
  .h-full {
    height: 100%;
  }
  .flex-1 {
    flex: 1 1 0%;
  }
  .justify-between {
    justify-content: space-between;
  }
  .justify-center {
    justify-content: center;
  }
  .grid-cols-4 {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .col-span-1 {
    grid-column: span 1 / span 1;
  }
  .col-span-3 {
    grid-column: span 3 / span 3;
  }
  .overflow-hidden {
    overflow: hidden;
  }
`;
document.head.appendChild(styleTag);

export default ComplaintTrackingChart;
